export namespace Effect { export interface Effect<A> { readonly _A?: A } export function succeed<A>(value: A): Effect<A> }
export namespace Layer { export interface Layer<A> { readonly _A?: A } export const empty: Layer<never>; export function effect<A, B>(tag: A, effect: Effect.Effect<B>): Layer<B>; export function flatMap<A, B>(layer: Layer<A>, fn: (value: A) => B): B; export function unwrap<A>(effect: Effect.Effect<Layer<A>>): Layer<A> }
export const Context: { Service<Self, A>(): (name: string) => new (...args: never[]) => A; get<A>(tag: A): A }
